export interface BrandLogoProps {
  /**
   * 'mark': Crown/A emblem vector
   * 'full': Complete vector mark + ARENAS wordmark
   * 'combo': Emblem vector + horizontal text label
   */
  variant?: 'mark' | 'full' | 'combo';
  /**
   * Size in pixels (height/width for mark, height for full/combo)
   * Defaults: mark=28, full=38, combo=28
   */
  size?: number;
  className?: string;
  priority?: boolean;
  /**
   * 'adaptive': switches between dark obsidian (light mode) and pure white (dark mode)
   * 'white': always pure white (ideal for dark surfaces)
   */
  theme?: 'adaptive' | 'white';
}

export function BrandLogo({
  variant = 'mark',
  size,
  className = '',
  theme = 'adaptive',
}: BrandLogoProps) {
  const colorClass =
    theme === 'white'
      ? 'text-white'
      : 'text-slate-900 dark:text-white transition-colors';

  if (variant === 'full') {
    const height = size ?? 38;
    // Aspect ratio 860 / 639 ≈ 1.346
    const width = Math.round(height * 1.346);

    return (
      <svg
        viewBox="0 0 860 639"
        fill="currentColor"
        width={width}
        height={height}
        className={`shrink-0 overflow-visible ${colorClass} ${className}`}
        aria-label="Arenas"
      >
        <path fillRule="evenodd" clipRule="evenodd" d={FULL_PATH} />
      </svg>
    );
  }

  if (variant === 'combo') {
    const iconSize = size ?? 28;
    return (
      <div className={`inline-flex items-center gap-2.5 shrink-0 ${className}`}>
        <BrandLogo variant="mark" size={iconSize} theme={theme} />
        <span className="font-['Geist'] text-xl font-bold tracking-tight text-slate-900 dark:text-white">
          Arenas
        </span>
      </div>
    );
  }

  // Variant: 'mark'
  const dimension = size ?? 28;

  return (
    <svg
      viewBox="0 0 500 500"
      fill="currentColor"
      width={dimension}
      height={dimension}
      className={`shrink-0 overflow-visible ${colorClass} ${className}`}
      aria-label="Arenas emblem"
    >
      <path fillRule="evenodd" clipRule="evenodd" d={MARK_PATH} />
    </svg>
  );
}
